// Template of oi-toolkit (skill oneidentity-imx-brand-theme): do not edit here, change the kit and reinstall.
import { ColorMap, OI_SHADES, OiShade } from './brand-ootb-colors';

/**
 * Runtime contract between the brand theme CSS (generated by the oi-toolkit kit) and BrandThemeService.
 * :root (identical in both theme files): --ccc-brand-light-class, --ccc-brand-dark-class, --ccc-brand-device-theme.
 * Scope of each theme: --ccc-brand-map-<shade>; dark theme only: --ccc-brand-dark-fg-<shade>,
 * --ccc-brand-dark-surface-<shade>, --ccc-brand-dark-fill, --ccc-brand-on-dark-fill.
 */

export interface BrandThemeConfig {
  readonly lightClass: string;
  readonly darkClass: string;
  /** brand: "Device theme" uses the brand themes; standard: it keeps the standard themes. */
  readonly deviceTheme: 'brand' | 'standard';
}

export interface BrandColorMaps {
  /** Map for the rules not scoped to .eui-dark-theme (both themes). */
  readonly base: ColorMap;
  /** Dark theme: text and icons of rules scoped to .eui-dark-theme. */
  readonly darkForeground?: ColorMap;
  /** Dark theme: backgrounds and borders of rules scoped to .eui-dark-theme. */
  readonly darkSurface?: ColorMap;
  /** Dark theme: fill that carries onDarkFill text (replaces the light blue fills with dark text). */
  readonly darkFill?: string;
  readonly onDarkFill?: string;
}

const PREFIX = '--ccc-brand-';

function read(style: CSSStyleDeclaration, name: string): string {
  return style.getPropertyValue(PREFIX + name).trim();
}

function readMap(style: CSSStyleDeclaration, prefix: string): ColorMap | null {
  const map: Partial<Record<OiShade, string>> = {};
  for (const shade of OI_SHADES) {
    const value = read(style, `${prefix}-${shade}`).toLowerCase();
    if (!value) {
      return null;
    }
    map[shade] = value;
  }
  return map as ColorMap;
}

/** Brand classes declared by the loaded theme CSS; null when no brand theme is loaded (yet). */
export function readBrandThemeConfig(doc: Document): BrandThemeConfig | null {
  const style = getComputedStyle(doc.documentElement);
  const lightClass = read(style, 'light-class');
  const darkClass = read(style, 'dark-class');
  if (!lightClass || !darkClass) {
    return null;
  }
  return { lightClass, darkClass, deviceTheme: read(style, 'device-theme') === 'standard' ? 'standard' : 'brand' };
}

/** Color maps declared by the active brand theme on <body>; null when its CSS is not loaded (yet). */
export function readBrandColorMaps(body: HTMLElement, dark: boolean): BrandColorMaps | null {
  const style = getComputedStyle(body);
  const base = readMap(style, 'map');
  if (!base) {
    return null;
  }
  if (!dark) {
    return { base };
  }
  const darkForeground = readMap(style, 'dark-fg');
  const darkSurface = readMap(style, 'dark-surface');
  const darkFill = read(style, 'dark-fill').toLowerCase();
  const onDarkFill = read(style, 'on-dark-fill').toLowerCase();
  if (!darkForeground || !darkSurface || !darkFill || !onDarkFill) {
    return null;
  }
  return { base, darkForeground, darkSurface, darkFill, onDarkFill };
}
